<?php require_once '../config/db.php'; require_once '../includes/auth.php'; require_role('faculty');
$st=$pdo->prepare("SELECT m.*,s.name subject_name,u.unit_name FROM materials m JOIN subjects s ON s.id=m.subject_id LEFT JOIN units u ON u.id=m.unit_id WHERE m.uploaded_by=? ORDER BY m.id DESC");$st->execute([$_SESSION['user_id']]);$rows=$st->fetchAll();
$page_title='My Materials';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='faculty';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">My Materials</h1><div class="table-card"><table><thead><tr><th>Title</th><th>Subject</th><th>Unit</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['unit_name']??'All')?></td><td><?=e(ucwords(str_replace('_',' ',$r['material_type'])))?></td><td><span class="tag"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>